import{_ as t,o as a,c as s,ak as r}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"UI overview","description":"","frontmatter":{"title":"UI overview","lang":"en-US"},"headers":[],"relativePath":"ui-overview.md","filePath":"ui-overview.md","lastUpdated":1788629440000}'),n={name:"ui-overview.md"};function o(i,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-overview" tabindex="-1">UI overview <a class="header-anchor" href="#ui-overview" aria-label="Permalink to &quot;UI overview&quot;">​</a></h1><p>This page is a <strong>map of the dashboard</strong> — where each view lives and what it&#39;s for. For the concepts behind a feature, follow the links to the dedicated pages (<a href="./concepts.html">Core concepts</a>, <a href="./flaky-tests.html">Flaky tests</a>, <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>, <a href="./reporter.html">Reporter</a>).</p><p>The dashboard is a single-page app built with <a href="https://ui.nuxt.com" target="_blank" rel="noreferrer">Nuxt UI</a>. It updates itself in real time over Server-Sent Events — pages refresh automatically when runs start or finish, so you never reload manually.</p><h2 id="inline-help" tabindex="-1">Inline help <a class="header-anchor" href="#inline-help" aria-label="Permalink to &quot;Inline help&quot;">​</a></h2><p>Blocks that aren&#39;t self-explanatory carry a small muted help icon (a circled question mark) next to their title. Click it for a short explanation and, where relevant, a <strong>Learn more</strong> link into these docs. The icon is keyboard-focusable and closes with <code>Esc</code>. Self-explanatory blocks (counters, search boxes) have no icon, keeping the UI uncluttered.</p><h2 id="open-in-ide" tabindex="-1">Open in IDE <a class="header-anchor" href="#open-in-ide" aria-label="Permalink to &quot;Open in IDE&quot;">​</a></h2><p>Every source path shown in the dashboard is clickable — hover it to reveal an <strong>open in IDE</strong> control that jumps to that file (and line) in VS Code or JetBrains. See <a href="./ide-integration.html">Open in IDE</a> for setup and the available methods.</p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><p>The sidebar gives access to the top-level sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>Home</td><td><code>/</code></td><td>Aggregate stats and activity across all projects</td></tr><tr><td>Analytics</td><td><code>/analytics</code></td><td>Cross-project trends, portfolio health, and insights over a chosen time window (see <a href="./analytics.html">Analytics</a>)</td></tr><tr><td>Projects</td><td><code>/projects</code></td><td>Full project listing with search and tag filters</td></tr><tr><td>Settings</td><td><code>/settings</code></td><td>Configuration, in two groups — <strong>Instance</strong> (account, users, notifications, storage) and <strong>Analysis</strong> (AI diagnosis, wasted time, timeout hygiene, tags, pull requests)</td></tr><tr><td>Setup <em>(admins)</em></td><td><code>/setup</code></td><td>Connect the reporter, and a checklist of which optional capabilities are actually active on this instance</td></tr><tr><td>API docs</td><td><code>/docs</code></td><td>Self-contained OpenAPI 3.1 reference (no external CDN) — browse endpoints and schemas, try requests live, copy cURL / fetch snippets</td></tr><tr><td>MCP server</td><td><code>/mcp</code></td><td>Setup guide for connecting AI clients (see <a href="./mcp.html">MCP server</a>)</td></tr></tbody></table><p>Everything else is reached by drilling into a project, run, or test case:</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th></tr></thead><tbody><tr><td>Project detail</td><td><code>/projects/:id</code></td></tr><tr><td>Project edit</td><td><code>/projects/:id/edit</code></td></tr><tr><td>Test cases (project)</td><td><code>/projects/:id/test-cases</code></td></tr><tr><td>Failure cluster</td><td><code>/failure-clusters/:id</code></td></tr><tr><td>Test run</td><td><code>/test-runs/:id</code></td></tr><tr><td>Test case</td><td><code>/test-cases/:id</code></td></tr></tbody></table><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Reachable from the sidebar at any time — not just before your first run. <strong>Administrators only</strong>, since it governs how results reach the instance and, in the desktop build, shows the local access token; when authentication is disabled every visitor is a virtual administrator, so it stays available on a default install. It carries the reporter setup steps (install, configure, run, plus <code>wrapConfig</code> and the capture fixtures under <strong>Go further</strong>) and a <strong>capability checklist</strong>: for each optional feature, whether this instance shows evidence of actually using it.</p><p>The checklist is deliberately evidence-based rather than config-based, so it answers the question an empty panel raises — <em>is this blank because it&#39;s broken, or because I never switched it on?</em> In the desktop build the page also carries the local instance&#39;s reporter URL and token, its MCP client configuration, the data location, and background-service control.</p><h2 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h2><p>A quick health check across all projects: a <strong>stat strip</strong> whose every number is a link (projects, failing now, flaky, average pass rate, runs today), an <strong>Open failures</strong> card, a <strong>Project health</strong> table (per-project run-history bars and a tendency badge), and <strong>recent activity</strong>. New instances show a getting-started wizard instead until the first run arrives.</p><p><strong>Open failures</strong> lists the failure clusters still open across the projects you can see, newest first by when they were last seen — each row shows the cluster name, its project, the number of affected tests, its age, the owner when known, its triage status and any pinned known-issue link. The row opens the cluster; reporters and admins can triage without leaving Home: <code>j</code> / <code>k</code> move the selection, <code>o</code> opens it, <code>r</code> resolves and <code>i</code> ignores.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p>A cross-project decision view — where Home answers <em>&quot;what&#39;s happening now&quot;</em>, Analytics answers <em>&quot;across projects, over time&quot;</em>. A <strong>scope bar</strong> at the top sets the period (last 7 / 30 / 90 days, last year, or all time) and the projects, then the same <strong>filter bar</strong> Home and each project use — environments and branches (multi-select) and a full-runs-only toggle; every widget re-aggregates against that scope.</p><p>Widgets are grouped into four bands, in reading order:</p><ul><li><strong>Where things stand</strong> — portfolio health, the insights feed, the pass-rate heatmap.</li><li><strong>Where the pain is</strong> — open failure clusters, the flakiest-tests leaderboard, wasted CI time.</li><li><strong>Which way it is going</strong> — regression velocity, CI time.</li><li><strong>Detail</strong> — the browser matrix, cross-project slow endpoints.</li></ul><p><a href="./timeline-markers.html">Timeline markers</a> overlay your deploys and infrastructure changes on the trend charts.</p><p>See <a href="./analytics.html">Analytics</a> for what each widget answers and how the periods are compared.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>The primary hub: instant <strong>text search</strong>, <strong>tag filters</strong>, and a table showing each project&#39;s run count, last-run date, duration, status, test pass/fail bar, report links, and actions. Create a project manually with <strong>New project</strong> (it&#39;s also created automatically on first result submission).</p><h2 id="project-detail" tabindex="-1">Project detail <a class="header-anchor" href="#project-detail" aria-label="Permalink to &quot;Project detail&quot;">​</a></h2><p>The complete history for one project. The header states the project&#39;s condition on entry — a <strong>status line</strong> with the latest run and its age, the pass rate over the last 20 runs, and the open clusters, flaky and quarantined counts, each a link to the tab that holds it. One <strong>filter bar</strong> (environment, branch, full-runs-only) scopes every list on the page and is remembered per project. The navbar keeps the notification bell and <strong>Import</strong> (admins); <strong>Edit</strong>, <strong>Test functions</strong>, <strong>Selections</strong>, <strong>Delete</strong> and <strong>Refresh</strong> live in a <strong>More</strong> menu.</p><p>Five tabs:</p><ul><li><strong>Runs</strong> — the run trend chart (timeline <strong>Markers</strong> open in a slide-over from the chart header, where they can be added, edited and deleted) over a table of every run with status, start time, duration, test counts, and browser badges. A row opens the run; selecting two runs and clicking <strong>Compare</strong> opens the newer run&#39;s <strong>Changes</strong> tab with the older as its baseline.</li><li><strong>Tests</strong> — every unique test with status, executed-only pass rate, result breakdown, average duration, and last run; searchable, filterable by status, <a href="./reporter.html#test-tags">tag</a>, owner, priority and last-run age (stale cases hidden by default). <strong>Group by File</strong> groups the tests under each spec file and carries that file&#39;s pass rate, flaky rate, failure count, test count and average time in the group header. A row opens the test&#39;s full history.</li><li><strong>Failures</strong> — one place for everything broken, switched with a segmented control: the <strong>Failure clusters</strong> (executions that failed the same way — see <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>), the <strong>Flaky</strong> tests scored by a composite flakiness metric with root-cause classification and impact ranking (see <a href="./flaky-tests.html#flaky-test-detection">Flaky tests</a>), each with a <strong>Quarantine</strong> action, and the <strong>Quarantine</strong> list — tests excluded from the <a href="./ci.html#blocking-a-merge">CI gate</a>&#39;s verdict while still running, each with its passing streak and whether it has earned a release. See <a href="./flaky-tests.html#quarantine-with-a-way-out">Quarantine</a>.</li><li><strong>Performance</strong> — average/P90 duration trends, a slowest-tests table, timeout opportunities, and the <a href="./flaky-tests.html#performance">slow endpoints</a> for a selected run; the AI-step coverage card appears when the project replays committed <a href="./ai-steps.html">AI-step artifacts</a>.</li><li><strong>Settings</strong> <em>(admins when auth is enabled, otherwise everyone)</em> — project <a href="./authentication.html#project-access">access</a> (members) and the edit form: label, description, tags, default branch, per-project SCM token, and <strong>AI diagnosis instructions</strong> (project-specific context combined with the global instructions for every diagnosis).</li></ul><p>Project <strong>import</strong> (<code>/projects/:id/import</code>, admins only) backfills runs recorded before you adopted Piwi from Playwright blob reports, checking each archive against the server&#39;s size limit and the project&#39;s existing imports before uploading anything. See <a href="./importing-runs.html">Importing past runs</a>.</p><h2 id="test-run-detail" tabindex="-1">Test run detail <a class="header-anchor" href="#test-run-detail" aria-label="Permalink to &quot;Test run detail&quot;">​</a></h2><p>A deep dive into a single run. The <strong>header</strong> shows status, <code>Run #N</code>, the run label and marker on the first line with the primary action (<strong>Copy retry command</strong> on a red run, the <strong>HTML report</strong> on a green one), then one facts line — started, duration, branch, commit, author, environment, CI build — with a <strong>Details</strong> popover holding the rest (shards, Playwright and Piwi versions, avg/P90 durations, wasted time, storage and every report, tags, links, custom data). Below it, <strong>one count bar</strong> carries the numbers on its segments (<em>N passed · N failed · N passed on retry · N skipped · N didn&#39;t run</em>, zero segments hidden); clicking a segment filters the Tests tab and switches to it. While a run is still <code>running</code>, a <strong>live progress bar</strong> and streaming results appear in real time, and each still-running row shows the <strong>step its worker is on right now</strong>, inline under the test title.</p><p>The right panel is tabbed:</p><ul><li><strong>Tests</strong> — every execution as one row (status, title, exceptional badges with a <code>+N</code> overflow, the failure headline and source path, duration, browser, retries, wasted time and its cluster). <strong>Group by</strong> <em>Cluster</em> (the default on a red run — each group header names the cluster, its test count and triage status, with an <em>Open cluster</em> link, and passing tests fold into a collapsed <em>Passed</em> group), <em>File</em> (with per-file tallies), <em>File + Describe</em> (the file nested by its describe blocks) or <em>None</em>. Search matches the title, path <strong>and</strong> error text; filter by status, browser, new regressions and newly flaky. Select failing rows for bulk triage (quarantine, or set the cluster status) in any grouping.</li><li><strong>Changes</strong> — what differs against <strong>one baseline</strong> (the last passing run on the same branch by default, or the run you pick — deep-linkable as <code>?baseline=&lt;runId&gt;</code>): new failures, fixed, still failing, newly flaky / passed on retry, the slower / faster tests, the commits landed since the baseline, and the environment fields that moved. The &quot;new failures&quot; count is computed once against that baseline. Disabled until the run finishes. See <a href="./flaky-tests.html#changes">Changes</a>.</li><li><strong>Timeline</strong> — a horizontal per-worker timeline of test execution, with a <em>Show hooks and waits</em> toggle to reveal setup, hook, fixture and wasted-wait spans; click a bar to jump to that test. Beneath it, the <strong>slowest tests</strong> and the <strong>worker distribution</strong> for the run.</li></ul><p>Administrators can <strong>delete</strong> the entire run and its files from the header&#39;s More menu, which also copies a run summary and refreshes.</p><h2 id="test-case-detail" tabindex="-1">Test case detail <a class="header-anchor" href="#test-case-detail" aria-label="Permalink to &quot;Test case detail&quot;">​</a></h2><p>Two pages live under this heading, and <a href="./concepts.html#execution">Core concepts</a> draws the line between them: an <strong>execution</strong> (<code>/test-run-cases/:id</code>) answers <em>&quot;why did this attempt fail?&quot;</em>, and a <strong>test case</strong> (<code>/test-cases/:id</code>) answers <em>&quot;how has this test behaved over time?&quot;</em>. Most links from a run land on an execution; the test&#39;s title links to the test case above it.</p><p>A failing execution reads top to bottom in one column: a <strong>header</strong> (status, title, the exceptional badges, the failing file and line, and Copy retry command, with a Details popover for the rest), the one-line <strong>headline</strong> (with the raw <strong>error</strong> one click away behind <em>Show raw error</em>), the <strong>other clues</strong>, then one <strong>evidence</strong> card whose content-level tabs — Timeline, Screen, Source, Network, Console, State, Performance — hold everything captured, deeper still when a trace is attached. Below the evidence, the <strong>Fix</strong> card gathers what to do (the locator fix, a fix-plan pointer, the diagnosis, how to verify, and the tests this failure blocked) and a <strong>history</strong> block strips this test&#39;s recent executions with its failing streak. All of it, plus the bundled trace viewer, is described in <a href="./evidence.html">Failure evidence</a>. The header&#39;s facts line shows the <strong>attempts</strong> as linked chips when a test retried, so &quot;how did this execution get here&quot; is answerable at a glance; every attempt is its own execution, and each chip links to that attempt&#39;s page while the one you are viewing is ringed.</p><p>The <strong>test history</strong> page (<code>/test-cases/:id</code>) opens on a single facts line under the title — how many runs, the pass rate, how many failed, the average duration, the flaky-run count and when it last ran — with <strong>Latest execution →</strong> and, in the desktop shell, <strong>Reproduce locally</strong> on the right. A <strong>duration trend</strong> chart plots each run coloured by status, and its footer is a strip of the recent executions where every square links to that execution. Below it, <strong>Recent executions</strong> lists each attempt as a row that opens the execution, and the <strong>failure clusters</strong> the test belongs to and its <strong>links</strong> follow.</p><h2 id="failure-cluster-detail" tabindex="-1">Failure cluster detail <a class="header-anchor" href="#failure-cluster-detail" aria-label="Permalink to &quot;Failure cluster detail&quot;">​</a></h2><p>Each cluster (<code>/failure-clusters/:id</code>) reads top to bottom in one column. The <strong>header</strong> states the cluster name and one facts line — error kind, occurrences, affected tests, the first- and last-seen runs, the owner and the known-issue link — with <strong>Re-run in CI</strong> (or Copy retry command) as its one action and the rest in a More menu (quarantine all affected tests, show diagnosis context, copy prompt, copy summary). Under it sits the <strong>triage control</strong>: a segmented <em>Open / Resolved / Ignored</em> that saves on click, a note, and — once a fix has landed — the <strong>fix verification</strong> badge with its one sentence (which verdict the runs support, the run and commit it landed in, how long the cluster stayed open) and, when triage and fix verification disagree, a one-click reconcile action. See <a href="./ai-diagnosis.html#did-the-fix-work">Did the fix work?</a>.</p><p>Below the header the failure reads as a one-line <strong>headline</strong> built from the cluster&#39;s latest occurrence (falling back to its stored sample error), with a <strong>Show raw error</strong> disclosure for the verbatim error and signature, then the deterministic <strong>clues</strong>. The <strong>evidence</strong> is one card whose content-level tabs — Timeline, Screen, Source, Network, Console, State, Performance — hold everything captured for the affected execution you select from the <em>from:</em> row on top; <strong>Open execution</strong> links through to that test-run case. Then one <strong>Fix</strong> card folds together what to do about the cluster: the <strong>AI diagnosis</strong> (an SCM-grounded LLM analysis whose cited evidence links back to the matching evidence tab, with a <strong>History</strong> control for its previous versions and a staleness banner that fires only while the failure is still live) — its stored result stays visible even with no provider configured — the <strong>locator fix</strong> for a broken locator (recommendation, provenance and alternatives, shown once), the <strong>verify</strong> command, and the whole <strong>fix plan</strong> as Markdown for a ticket or an agent (see <a href="./ai-diagnosis.html#fix-plans">Fix plans</a>). Below the Fix card come <strong>what changed</strong> (the SCM diff since the last green run, with a baseline-commit picker and commit browser), the <strong>affected tests</strong> (a selectable list whose bulk bar moves tests to a new cluster or quarantines them; each row links to its latest execution), and a <strong>history</strong> block with the cluster&#39;s occurrences, diagnosis-version count and fix-verification date. Full detail: <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>.</p><h2 id="offline-export" tabindex="-1">Offline export <a class="header-anchor" href="#offline-export" aria-label="Permalink to &quot;Offline export&quot;">​</a></h2><p>An <strong>Export</strong> button on a test-case execution (<code>/test-run-cases/:id</code>) and on a failure cluster (<code>/failure-clusters/:id</code>) writes the investigation to an HTML, ZIP, PDF, Markdown or JSON file that opens with no network and no Piwi server. See <a href="./offline-export.html">Offline export</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>What it does</th></tr></thead><tbody><tr><td>General</td><td><code>/settings</code></td><td>Basic app configuration; a <strong>Reset Demo</strong> button in demo mode</td></tr><tr><td>Account</td><td><code>/settings/account</code></td><td>Your display name, email, password, and <strong>connected accounts</strong> (link/unlink Google or GitHub — see <a href="./authentication.html#oauth-google-github">OAuth</a>)</td></tr><tr><td>Users</td><td><code>/settings/users</code></td><td>User accounts, roles, project access, and API keys (shown once, stored hashed) — see <a href="./authentication.html">Authentication</a></td></tr><tr><td>Storage</td><td><code>/settings/storage</code></td><td>Storage stats and cleanup (bulk-delete runs older than N days) — see <a href="./storage.html#storage-management">Storage</a></td></tr><tr><td>Tags</td><td><code>/settings/tags</code></td><td>Create, color, edit, and delete the tags used to organize projects</td></tr><tr><td>Pull requests</td><td><code>/settings/pr-feedback</code></td><td>What Piwi posts back to a pull request when a run finishes — see <a href="./ci.html#pull-request-feedback">Pull-request feedback</a></td></tr><tr><td>Performance</td><td><code>/settings/performance</code></td><td>Wasted-time patterns (which Playwright waits count as &quot;wasted time&quot;) and timeout-hygiene thresholds (oversized per-test timeouts, stale <code>test.slow()</code> marks) — see <a href="./configuration.html#wasted-time">Configuration</a></td></tr><tr><td>AI</td><td><code>/settings/ai</code></td><td>Provider/model roles, auto-diagnose, global instructions, and context limits — see <a href="./ai-diagnosis.html#enabling-ai-diagnosis">AI diagnosis</a></td></tr><tr><td>Notifications</td><td><code>/settings/notifications</code></td><td>Channels, subscriptions, and SMTP — see <a href="./notifications.html">Notifications &amp; alerts</a></td></tr></tbody></table><p>Where an environment variable backs a setting, the field is shown read-only with a lock badge and the env var name (see <a href="./configuration.html">Configuration</a>).</p><h2 id="real-time-updates" tabindex="-1">Real-time updates <a class="header-anchor" href="#real-time-updates" aria-label="Permalink to &quot;Real-time updates&quot;">​</a></h2><p>The dashboard uses Server-Sent Events so it never needs a manual refresh:</p><ul><li><strong>Global stream</strong> (<code>/api/stream</code>) — tells every connected client when a run starts, finishes, or is submitted; pages re-fetch their data.</li><li><strong>Per-run stream</strong> (<code>/api/test-runs/:id/stream</code>) — drives the live progress on the run detail page during a streaming run.</li></ul><h2 id="live-demo" tabindex="-1">Live demo <a class="header-anchor" href="#live-demo" aria-label="Permalink to &quot;Live demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> runs entirely in your browser (in-memory SQLite) and adds two things the real app doesn&#39;t need:</p><p><strong>Simulate a test run</strong> — the demo banner replays the exact streaming protocol a Piwi reporter speaks during a real run, so you can watch one arrive live. Scenarios: a passing run, a run with failures (joining a known cluster plus a brand-new one), flaky retries, a performance regression, an interrupted run, and a cross-browser run. Each creates a real run in the in-browser database, so worker timeline, failure clusters, and history comparisons all behave exactly as they would against a server.</p><p><strong>Acting as</strong> — the demo runs with authentication conceptually enabled. Switch between pre-seeded identities (an admin, a CI reporter, and several project-scoped users) to see how <a href="./authentication.html#project-access">project access</a> changes what each user sees. Acting as the admin, you can change affectations live and then switch users to see the effect.</p><h2 id="responsive-dark-mode" tabindex="-1">Responsive &amp; dark mode <a class="header-anchor" href="#responsive-dark-mode" aria-label="Permalink to &quot;Responsive &amp; dark mode&quot;">​</a></h2><p>The dashboard is fully responsive — sidebar navigation on desktop, collapsible sidebar and horizontally scrolling tables on tablet, and a stacked/hamburger layout on mobile. It supports light and dark themes, following the system preference by default, with a manual toggle in the sidebar.</p>',57)])])}const p=t(n,[["render",o]]);export{g as __pageData,p as default};
